s('about.title', 'Rólunk', 'About us', 'Über uns')
s('about.sub', 'A Chartolj! célja, hogy a pénzügyi piacok megértése átlátható, gyakorlatias és felelős legyen.', 'Chartolj! aims to make understanding financial markets clear, practical and responsible.', 'Chartolj! möchte das Verständnis der Finanzmärkte transparent, praxisnah und verantwortungsvoll machen.')
s('about.is.t', 'Mi a Chartolj!', 'What Chartolj! is', 'Was Chartolj! ist')
s('about.is.1', 'Pénzügyi oktatási platform strukturált leckékkel, kvízekkel és haladáskövetéssel.', 'A financial education platform with structured lessons, quizzes and progress tracking.', 'Eine Finanzbildungsplattform mit strukturierten Lektionen, Quizzen und Fortschrittsverfolgung.')
s('about.is.2', 'Szimulált kereskedési terminál grafikonokkal, indikátorokkal és rajzeszközökkel.', 'A simulated trading terminal with charts, indicators and drawing tools.', 'Ein simuliertes Handelsterminal mit Charts, Indikatoren und Zeichenwerkzeugen.')
s('about.is.3', 'Eszköztár több mint 200 kalkulátorral és elemzővel.', 'A toolbox with more than 200 calculators and analysers.', 'Eine Toolbox mit über 200 Rechnern und Analysetools.')
s('about.not.t', 'Mi nem a Chartolj!', 'What Chartolj! is not', 'Was Chartolj! nicht ist')
s('about.not.1', 'Nem bróker, nem befektetési vállalkozás és nem szabályozott pénzügyi szolgáltató.', 'Not a broker, an investment firm or a regulated financial services provider.', 'Kein Broker, kein Wertpapierunternehmen und kein regulierter Finanzdienstleister.')
s('about.not.2', 'Nem nyújt személyre szabott befektetési tanácsot, és nem ígér hozamot.', 'It gives no personalised investment advice and promises no returns.', 'Es bietet keine persönliche Anlageberatung und verspricht keine Renditen.')
s('about.not.3', 'A szimulált megbízások nem kerülnek végrehajtásra valós piacon.', 'Simulated orders are never executed on a real market.', 'Simulierte Orders werden niemals an einem realen Markt ausgeführt.')
s('about.company.t', 'Cégadatok', 'Company information', 'Unternehmensangaben')
s('about.company.d', 'A cégnév, székhely, cégjegyzékszám és adószám jogi jóváhagyás után kerül ide. Addig nem közlünk kitalált adatokat.', 'Company name, registered office, registration and tax numbers will be added after legal approval. Until then we publish no invented details.', 'Firmenname, Sitz, Register- und Steuernummer werden nach rechtlicher Freigabe ergänzt. Bis dahin veröffentlichen wir keine erfundenen Angaben.')
s('about.values', 'Alapelveink', 'Our principles', 'Unsere Grundsätze')
s('about.v1.t', 'Őszinteség', 'Honesty', 'Ehrlichkeit')
s('about.v1.d', 'A szimulált adatot szimuláltnak nevezzük, a ki nem épített funkciót pedig nem hirdetjük.', 'Simulated data is called simulated, and features that are not built are not advertised.', 'Simulierte Daten nennen wir simuliert, und nicht gebaute Funktionen bewerben wir nicht.')
s('about.v2.t', 'Pontosság', 'Accuracy', 'Genauigkeit')
s('about.v2.d', 'A kalkulátorok standard képleteket használnak, és ismert példákkal vannak tesztelve.', 'Calculators use standard formulas and are tested against known examples.', 'Die Rechner nutzen Standardformeln und sind mit bekannten Beispielen getestet.')
s('about.v3.t', 'Felelősség', 'Responsibility', 'Verantwortung')
s('about.v3.d', 'A kockázatot hangsúlyozzuk, és nem ösztönzünk meggondolatlan kereskedésre.', 'We emphasise risk and never encourage reckless trading.', 'Wir betonen das Risiko und ermutigen nie zu unbedachtem Handel.')

# ---------------------------------------------------------------- FAQ
s('faq.title', 'Gyakori kérdések', 'Frequently asked questions', 'Häufige Fragen')
s('faq.sub', 'Röviden és őszintén a Chartolj! működéséről.', 'Short, honest answers about how Chartolj! works.', 'Kurze, ehrliche Antworten dazu, wie Chartolj! funktioniert.')
for i, (qh, qe, qd, ah, ae, ad) in enumerate([
    ('Bróker a Chartolj!?', 'Is Chartolj! a broker?', 'Ist Chartolj! ein Broker?', 'Nem. A Chartolj! oktatási és elemző termék szimulált kereskedéssel. Nem hajt végre valós megbízásokat, és nem kezel ügyfélpénzt.', 'No. Chartolj! is an educational and analytical product with simulated trading. It does not execute real orders or hold client money.', 'Nein. Chartolj! ist ein Bildungs- und Analyseprodukt mit simuliertem Handel. Es führt keine echten Orders aus und verwahrt kein Kundengeld.'),
    ('Valós az árfolyam, amit látok?', 'Are the prices I see real?', 'Sind die Kurse, die ich sehe, echt?', 'Kriptovalutáknál a Binance nyilvános piaci adatát használjuk, devizapároknál az EKB napi referenciaárfolyamát. A többi instrumentum jelenleg szimulált DEMO érték, és így is van jelölve.', 'For crypto we use Binance public market data and for forex the ECB daily reference rate. Other instruments are currently simulated DEMO values and are labelled as such.', 'Für Krypto nutzen wir öffentliche Binance-Marktdaten, für Forex den täglichen EZB-Referenzkurs. Andere Instrumente sind derzeit simulierte DEMO-Werte und entsprechend gekennzeichnet.'),
    ('Kereskedhetek valódi pénzzel?', 'Can I trade with real money?', 'Kann ich mit echtem Geld handeln?', 'Nem. A terminál szimulált számlával működik, a szimulált megbízások sosem jutnak el valós piacra.', 'No. The terminal works with a simulated account and simulated orders never reach a real market.', 'Nein. Das Terminal arbeitet mit einem simulierten Konto, und simulierte Orders erreichen nie einen realen Markt.'),
    ('Mennyibe kerül a Premium?', 'How much does Premium cost?', 'Was kostet Premium?', 'Az árakat a háttérrendszer adja meg, jóváhagyás után jelennek meg a Prémium oldalon. Addig nem közlünk összeget.', 'Prices are supplied by the backend and appear on the Premium page once approved. Until then we show no amounts.', 'Die Preise kommen aus dem Backend und erscheinen nach Freigabe auf der Premium-Seite. Bis dahin nennen wir keine Beträge.'),
    ('Hogyan lehet előfizetni?', 'How do I subscribe?', 'Wie schließe ich ein Abo ab?', 'Androidon a Google Play Billingen keresztül. Webes fizetési szolgáltató jelenleg nincs csatlakoztatva. A jogosultságot mindig a szerver ellenőrzi.', 'On Android through Google Play Billing. No web payment provider is connected at the moment. Entitlement is always verified on the server.', 'Auf Android über Google Play Billing. Derzeit ist kein Web-Zahlungsanbieter angebunden. Die Berechtigung wird immer vom Server geprüft.'),
    ('Mely nyelveken érhető el az oldal?', 'Which languages does the site support?', 'In welchen Sprachen ist die Website verfügbar?', 'Magyarul, angolul és németül. Az alkalmazás tananyagai jelenleg magyar nyelvűek.', 'Hungarian, English and German. The app’s lesson content is currently Hungarian.', 'Auf Ungarisch, Englisch und Deutsch. Die Lerninhalte der App sind derzeit ungarisch.'),
    ('Mit tárol a weboldal a böngészőmben?', 'What does the website store in my browser?', 'Was speichert die Website in meinem Browser?', 'Csak a nyelvi beállításodat és a figyelőlistádat, a böngésződ helyi tárolójában. Követő vagy hirdetési sütit nem használunk. Törölheted a Süti- és adatbeállítások oldalon.', 'Only your language setting and watchlist, in your browser’s local storage. We use no tracking or advertising cookies. You can clear it on the Cookie & data preferences page.', 'Nur deine Spracheinstellung und deine Watchlist im lokalen Speicher deines Browsers. Wir verwenden keine Tracking- oder Werbe-Cookies. Du kannst sie auf der Seite Cookie- und Dateneinstellungen löschen.'),
    ('Ígérhet a Chartolj! hozamot?', 'Does Chartolj! promise returns?', 'Verspricht Chartolj! Renditen?', 'Soha. A kereskedés kockázatos, a tananyag pedig általános oktatási tartalom, nem személyre szabott tanács.', 'Never. Trading is risky and the material is general education, not personalised advice.', 'Niemals. Handel ist riskant, und die Inhalte sind allgemeine Bildung, keine persönliche Beratung.')]):
    s('faq.q%d' % i, qh, qe, qd); s('faq.a%d' % i, ah, ae, ad)

